 export function prorate(oldPriceCents: number, newPriceCents: number, daysUsed: number, daysInPeriod: number): number {
-  const remaining = daysInPeriod - daysUsed;
-  const credit = Math.round((oldPriceCents * remaining) / daysInPeriod);
-  const charge = Math.round((newPriceCents * remaining) / daysInPeriod);
-  return charge - credit;
+  if (daysInPeriod <= 0) {
+    throw new RangeError("daysInPeriod must be positive");
+  }
+  const remaining = Math.max(0, daysInPeriod - daysUsed);
+  const credit = Math.floor((oldPriceCents * remaining) / daysInPeriod);
+  const charge = Math.ceil((newPriceCents * remaining) / daysInPeriod);
+  // A downgrade never charges: the difference becomes account credit elsewhere.
+  return Math.max(0, charge - credit);
 }
